// Serve the latest meter snapshot through the modbus-server node's holding
// registers.
//
// The server node's input-message write path is BYTE-addressed with a
// factor-8 multiplier (bufferAddress = payload.address * 8 into the raw
// jsmodbus buffer), while the Modbus TCP read path serves register R from
// byte offset R * 2. Per-register writes therefore land 4 read-registers
// apart and can never form a contiguous float32 pair. The only mapping that
// yields a contiguous, readable block is a SINGLE byte-array write of the
// whole register block at address (BASE_REGISTER * 2) / 8 — the array path
// copies bytes contiguously into the buffer.
const BASE_REGISTER = 19000;                   // Janitza UMG 96RM layout
const BLOCK_REGISTERS = 66;                    // registers 19000..19065
const WRITE_ADDRESS = (BASE_REGISTER * 2) / 8; // = 4750; BASE must be divisible by 4

const REGISTER_OFFSETS = {                     // register offset from BASE_REGISTER
    active_power_l1_w: 0,
    active_power_l2_w: 2,
    active_power_l3_w: 4,
    active_power_total_w: 6,
    voltage_l1_v: 20,
    voltage_l2_v: 22,
    voltage_l3_v: 24,
    current_l1_a: 40,
    current_l2_a: 42,
    current_l3_a: 44,
    power_factor: 60,
    total_energy_kwh: 62,
    frequency_hz: 64
};

const meters = global.get('latest_meters') || [];
if (meters.length === 0) {
    return null;
}

const meterIndex = Number(env.get('METER_INDEX') || 0);
const meter = meters[meterIndex] || meters[0];
if (!meter || !meter.readings) {
    return null;
}

const r = meter.readings;
const phases = [r.active_power_l1_w, r.active_power_l2_w, r.active_power_l3_w];
const allPhasesPresent = phases.every((v) => typeof v === 'number' && !Number.isNaN(v));
const totalActiveW = allPhasesPresent ? phases.reduce((a, b) => a + b, 0) : undefined;

const values = {
    active_power_l1_w: r.active_power_l1_w,
    active_power_l2_w: r.active_power_l2_w,
    active_power_l3_w: r.active_power_l3_w,
    active_power_total_w: totalActiveW,
    voltage_l1_v: r.voltage_l1_v,
    voltage_l2_v: r.voltage_l2_v,
    voltage_l3_v: r.voltage_l3_v,
    current_l1_a: r.current_l1_a,
    current_l2_a: r.current_l2_a,
    current_l3_a: r.current_l3_a,
    power_factor: r.power_factor,
    total_energy_kwh: r.total_energy_kwh,
    frequency_hz: r.frequency_hz
};

const block = Buffer.alloc(BLOCK_REGISTERS * 2);
let written = 0;
for (const [field, offset] of Object.entries(REGISTER_OFFSETS)) {
    const value = values[field];
    if (typeof value !== 'number' || Number.isNaN(value)) continue;
    block.writeFloatBE(value, offset * 2);
    written++;
}

if (written === 0) {
    return null;
}

flow.set('modbus_last_write_count', written);
flow.set('modbus_last_write_meter', meter.meter_id);

// disableMsgOutput: the server node's passthrough outputs are unwired;
// suppressing them avoids cloning the full register buffers every second.
node.send({ payload: { value: Array.from(block), register: 'holding', address: WRITE_ADDRESS, disableMsgOutput: 1 } });
return null;
